import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000/api';

const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000,
});

// Tự động thêm token vào header
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Xử lý response tập trung
api.interceptors.response.use(
  (response) => {
    // Trả về data từ response
    return response.data;
  },
  (error) => {
    // Xử lý lỗi tập trung
    if (error.response) {
      switch (error.response.status) {
        case 400:
          return Promise.reject(new Error(error.response.data.message || 'Dữ liệu không hợp lệ'));
        case 401:
          localStorage.removeItem('token');
          window.location.href = '/login';
          return Promise.reject(new Error('Phiên đăng nhập hết hạn'));
        case 403:
          return Promise.reject(new Error('Bạn không có quyền truy cập'));
        case 404:
          return Promise.reject(new Error('Tài nguyên không tồn tại'));
        case 500:
          return Promise.reject(new Error('Lỗi server'));
        default:
          return Promise.reject(new Error('Lỗi không xác định'));
      }
    }
    return Promise.reject(error);
  }
);

// API Auth
export const authAPI = {
  register: (userData) => api.post('/auth/signup', {
    username: userData.username,
    email: userData.email,
    password: userData.password
  }),
  
  login: (credentials) => api.post('/auth/login', {
    usernameOrEmail: credentials.usernameOrEmail,
    password: credentials.password
  }),
  
  logout: () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    return Promise.resolve();
  }
};

export default api;
